#include "model.hpp"
#include "image_io.hpp"
#include "backend.hpp"

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <vector>

// Multi-model graph-cache safety smoke. The lever-1 persistent graph cache lives
// on the PROCESS-GLOBAL fd::Backend and keys entries by a fingerprint that folds
// each model pack's WEIGHT data pointers. Risk: free a ModelLoader, let a later
// model reallocate the same address, and a stale entry could false-hit and replay
// a cached graph whose leaves point at the freed weights (UB / wrong output).
//
// This proves the invalidate-on-free hardening (~ModelLoader ->
// invalidate_graph_cache_for_weights -> Backend::invalidate_weights_buffer):
//
//   Phase 0  reference: one isolated load + embed, then shutdown_backend() to
//            drop the global backend and its whole cache.
//   Phase 1  load A, embed (populates the cache across the detect/align/arcface
//            graphs), free A; assert the cache is now EMPTY (every entry
//            references A's one weights buffer, so all are purged). With nothing
//            left, there is no entry for a later same-address model to false-hit.
//   Phase 2  load B (a fresh instance of the SAME pack; the allocator very likely
//            hands back A's just-freed weights-buffer address). Its first embed
//            MUST register cache MISSes (not stale hits) and MUST match the
//            reference bit-for-bit.
//   Phase 3  embed the same image on B again: MUST be served from cache HITs and
//            be bit-identical (same-model reload keeps the hot cache).
//
// RC-77 skip when the model/image env vars are unset.

static int fail(const char* msg) { std::fprintf(stderr, "cache-safety: %s\n", msg); return 1; }

int main() {
    const char* gguf = std::getenv("FACEDETECT_TEST_GGUF");
    const char* imgp = std::getenv("FACEDETECT_TEST_IMAGE");
    if (!gguf || !imgp) return 77;

    fd::Image img;
    if (!fd::load_image_rgb(imgp, img)) return 77;

    // --- Phase 0: isolated reference embedding. -------------------------------
    std::vector<float> ref;
    {
        auto m = fd::Model::load(gguf);
        if (!m) return 77;
        ref = m->embed(img);
    }
    fd::shutdown_backend();   // fresh global backend + empty cache for the test
    if (ref.empty()) return fail("reference embedding empty");

    // --- Phase 1: A loaded, embedded, freed -> cache must be purged. -----------
    {
        auto A = fd::Model::load(gguf);
        if (!A) return 77;
        (void)A->embed(img);
        if (fd::global_backend().cache_size() == 0)
            return fail("expected A to populate the graph cache");
        A.reset();   // ~Model -> ~ModelLoader frees weights -> invalidate cache
        if (fd::global_backend().cache_size() != 0)
            return fail("cache NOT invalidated on model free (stale-hit risk)");
    }

    // --- Phase 2: B at the (likely) reused address must MISS and be correct. ---
    const uint64_t miss0 = fd::global_backend().cache_misses();
    auto B = fd::Model::load(gguf);
    if (!B) return 77;
    std::vector<float> eB = B->embed(img);
    if (fd::global_backend().cache_misses() <= miss0)
        return fail("B's first embed produced no MISS (possible stale hit)");
    if (eB.size() != ref.size()) return fail("B embedding size mismatch");
    double dmax = 0.0;
    for (size_t i = 0; i < ref.size(); ++i)
        dmax = std::max(dmax, (double)std::fabs(eB[i] - ref[i]));
    if (dmax > 1e-6) {
        std::fprintf(stderr, "cache-safety: B diverged from reference, max|d|=%g\n", dmax);
        return 1;
    }

    // --- Phase 3: same-model reload still HITS (and is bit-identical). ---------
    const uint64_t hits0 = fd::global_backend().cache_hits();
    std::vector<float> eB2 = B->embed(img);
    if (fd::global_backend().cache_hits() <= hits0)
        return fail("same-model reload produced no cache HIT (perf regression)");
    if (eB2.size() != eB.size()) return fail("HIT embedding size mismatch");
    for (size_t i = 0; i < eB.size(); ++i)
        if (eB2[i] != eB[i]) return fail("cache HIT output not bit-identical");

    fd::shutdown_backend();
    std::printf("cache-safety: PASS (purge-on-free; B MISS+correct; reload HIT bit-identical)\n");
    return 0;
}

#pragma once
#include "model_loader.hpp"
#include "detect.hpp"
#include "image_io.hpp"

#include <memory>
#include <string>
#include <vector>

namespace fd {

// One analyzed face: detection + (optionally) the embedding and genderage
// attributes filled in by the pipeline.
struct Face {
    Detection det;                  // box + score + landmarks
    std::vector<float> embedding;   // L2-normalized, embed_dim (empty if not run)
    int   age    = -1;              // genderage age (-1 if not run)
    char  gender = '?';             // 'M' / 'F' / '?' (not run)
    float spoof_score = -1.0f;      // anti-spoof live-ness score (-1 if not run)
};

// Load-once face-recognition context.
//
// Loads a GGUF model pack ONCE (owns the ModelLoader) and reuses it across many
// calls - this is what the flat C-API holds. The stage components (detector,
// aligner, recognizer, genderage, anti-spoof) are lightweight views over the
// ModelLoader, constructed per call; the expensive GGUF parse + weight mapping
// happens exactly once, in load().
class Model {
public:
    // Loads the GGUF pack at `gguf_path`. Returns nullptr on failure (no throw).
    static std::unique_ptr<Model> load(const std::string& gguf_path);

    // Detect all faces in an image (boxes + scores + landmarks), no embedding.
    // Throws std::runtime_error on failure.
    std::vector<Detection> detect(const Image& img) const;

    // Detect the primary face, align (norm_crop) and run ArcFace, returning the
    // L2-normalized embedding (length config().embed_dim). Throws on failure
    // (no face found, unsupported pack, ...).
    std::vector<float> embed(const Image& img) const;

    // Analyze every face: detect + genderage (and anti-spoof when present).
    // Throws std::runtime_error on failure.
    std::vector<Face> analyze(const Image& img) const;

    // Liveness verdict for one detected face: true when the MiniFASNet ensemble
    // judges it real (averaged "real" probability >= 0.5). Returns true (no veto)
    // when the pack carries no anti-spoof models. Throws on graph failure.
    bool is_real(const Image& img, const Detection& d) const;

    const FaceConfig& config() const { return loader_.config(); }
    const ModelLoader& loader() const { return loader_; }

    Model(const Model&) = delete;
    Model& operator=(const Model&) = delete;

private:
    Model() = default;
    ModelLoader loader_;
};

} // namespace fd

#include "model.hpp"
#include "common.hpp"
#include "align.hpp"
#include "detect.hpp"
#include "arcface_graph.hpp"
#include "sface_graph.hpp"
#include "genderage_graph.hpp"
#include "antispoof_graph.hpp"
#include "backend.hpp"

#include <algorithm>
#include <stdexcept>

namespace fd {

std::unique_ptr<Model> Model::load(const std::string& gguf_path) {
    auto m = std::unique_ptr<Model>(new Model());
    if (!m->loader_.load(gguf_path)) {
        FD_LOG("Model::load: failed to load %s", gguf_path.c_str());
        return nullptr;
    }
    return m;
}

std::vector<Detection> Model::detect(const Image& img) const {
    if (img.empty()) throw std::runtime_error("facedetect: empty image");
    // Detector graph stage is deferred; scrfd_detect is a stub for now.
    return scrfd_detect(loader_, img);
}

std::vector<float> Model::embed(const Image& img) const {
    if (img.empty()) throw std::runtime_error("facedetect: empty image");
    // Pick the primary (largest-area) detection, norm_crop to the 112x112
    // aligned RGB crop, then run the ArcFace IResNet50 embed graph (which is
    // L2-normalized internally), matching insightface's primary.normed_embedding.
    std::vector<Detection> dets = scrfd_detect(loader_, img);
    if (dets.empty()) throw std::runtime_error("facedetect: no face detected");
    const Detection& primary = *std::max_element(
        dets.begin(), dets.end(), [](const Detection& a, const Detection& b) {
            return (a.x2 - a.x1) * (a.y2 - a.y1) < (b.x2 - b.x1) * (b.y2 - b.y1);
        });
    Image aligned;
    if (!norm_crop(img, primary.landmarks, aligned, (int)loader_.config().rec_input_size))
        throw std::runtime_error("facedetect: alignment failed");
    // SFace (OpenCV-Zoo, Apache) shares the 5-point arcface_dst template that
    // norm_crop already uses (OpenCV FaceRecognizerSF::alignCrop), so the aligned
    // crop is the same; only the recognizer graph + preprocessing differ. Dispatch
    // on the configured recognizer.
    if (loader_.config().recognizer == "sface")
        return sface_embed(loader_, aligned, global_backend());
    return arcface_embed(loader_, aligned, global_backend());
}

std::vector<Face> Model::analyze(const Image& img) const {
    if (img.empty()) throw std::runtime_error("facedetect: empty image");
    // Per detected face, run the genderage head when the pack carries it (the `ga.`
    // weights). Anti-spoof remains a later stage. Each face is independently warped
    // to the 96x96 genderage crop (its own detection box), so multi-face images get
    // per-face age/gender rather than only the primary's.
    std::vector<Detection> dets = scrfd_detect(loader_, img);
    const bool have_ga = loader_.config().genderage_present;
    std::vector<Face> faces;
    faces.reserve(dets.size());
    for (const Detection& d : dets) {
        Face f;
        f.det = d;
        if (have_ga) {
            std::pair<int, int> ga = genderage(loader_, img, d, global_backend());
            f.gender = (ga.first == 1) ? 'M' : 'F';
            f.age = ga.second;
        }
        faces.push_back(std::move(f));
    }
    return faces;
}

bool Model::is_real(const Image& img, const Detection& d) const {
    if (!loader_.config().antispoof_present) return true;  // no models -> no veto
    return antispoof_score(*this, img, d) >= 0.5f;
}

} // namespace fd

#include "facedetect_capi.h"
#include "model.hpp"
#include "image_io.hpp"

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <exception>
#include <memory>
#include <new>
#include <string>
#include <vector>

// ABI version. Bump on breaking changes (see facedetect_capi.h changelog).
// v1: initial surface.
#define FACEDETECT_CAPI_ABI_VERSION 1

// The opaque context: a loaded model pack plus a buffer for the last error.
struct facedetect_ctx {
    std::unique_ptr<fd::Model> model;
    std::string last_error;
};

namespace {

// Record a last-error message on the context (no-op on NULL ctx).
void set_error(facedetect_ctx* ctx, const std::string& msg) {
    if (ctx) ctx->last_error = msg;
}

// malloc a NUL-terminated copy of `s` so a C consumer frees it with free()
// (matching facedetect_capi_free_string). Returns NULL on OOM.
char* dup_to_c(const std::string& s) {
    char* buf = static_cast<char*>(std::malloc(s.size() + 1));
    if (!buf) return nullptr;
    std::memcpy(buf, s.data(), s.size());
    buf[s.size()] = '\0';
    return buf;
}

// malloc a copy of a float vector for return across the C boundary. Returns NULL
// on OOM or empty input.
float* dup_vec(const std::vector<float>& v) {
    if (v.empty()) return nullptr;
    float* buf = static_cast<float*>(std::malloc(v.size() * sizeof(float)));
    if (!buf) return nullptr;
    std::memcpy(buf, v.data(), v.size() * sizeof(float));
    return buf;
}

// Append `s` to `out` as a JSON string literal (with surrounding quotes),
// escaping ", \\, and control characters.
void json_escape(std::string& out, const std::string& s) {
    out += '"';
    for (char c : s) {
        switch (c) {
            case '"':  out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n";  break;
            case '\r': out += "\\r";  break;
            case '\t': out += "\\t";  break;
            default:
                if ((unsigned char)c < 0x20) {
                    char b[8];
                    std::snprintf(b, sizeof(b), "\\u%04x", (unsigned char)c);
                    out += b;
                } else {
                    out += c;
                }
        }
    }
    out += '"';
}

// Serialize a list of faces (detection-only fields) to the detect JSON shape.
std::string detections_to_json(const std::vector<fd::Detection>& dets) {
    std::string out = "{\"faces\":[";
    for (size_t i = 0; i < dets.size(); ++i) {
        const fd::Detection& d = dets[i];
        if (i) out += ',';
        char b[256];
        std::snprintf(b, sizeof(b),
                      "{\"score\":%.4f,\"box\":[%.2f,%.2f,%.2f,%.2f],\"landmarks\":[",
                      d.score, d.x1, d.y1, d.x2, d.y2);
        out += b;
        for (int k = 0; k < 5; ++k) {
            if (k) out += ',';
            std::snprintf(b, sizeof(b), "[%.2f,%.2f]", d.landmarks[k][0], d.landmarks[k][1]);
            out += b;
        }
        out += "]}";
    }
    out += "]}";
    return out;
}

} // namespace

extern "C" int facedetect_capi_abi_version(void) { return FACEDETECT_CAPI_ABI_VERSION; }

extern "C" facedetect_ctx* facedetect_capi_load(const char* gguf_path) {
    if (!gguf_path) return nullptr;
    try {
        auto ctx = std::make_unique<facedetect_ctx>();
        ctx->model = fd::Model::load(gguf_path);
        if (!ctx->model) return nullptr;   // load failure: nothing to return
        return ctx.release();
    } catch (...) {
        return nullptr;
    }
}

extern "C" void facedetect_capi_free(facedetect_ctx* ctx) { delete ctx; }

extern "C" const char* facedetect_capi_last_error(facedetect_ctx* ctx) {
    return ctx ? ctx->last_error.c_str() : "";
}

extern "C" void facedetect_capi_free_string(char* s) { std::free(s); }

extern "C" void facedetect_capi_free_vec(float* v) { std::free(v); }

extern "C" int facedetect_capi_embed_path(facedetect_ctx* ctx, const char* image_path,
                                          float** out_vec, int* out_dim) {
    if (!ctx || !ctx->model || !image_path || !out_vec || !out_dim) return 1;
    try {
        fd::Image img;
        if (!fd::load_image_rgb(image_path, img)) {
            set_error(ctx, std::string("failed to load image: ") + image_path);
            return 2;
        }
        std::vector<float> emb = ctx->model->embed(img);
        float* buf = dup_vec(emb);
        if (!buf) { set_error(ctx, "out of memory"); return 3; }
        *out_vec = buf;
        *out_dim = (int)emb.size();
        return 0;
    } catch (const std::exception& e) {
        set_error(ctx, e.what());
        return 4;
    } catch (...) {
        set_error(ctx, "unknown error");
        return 4;
    }
}

extern "C" int facedetect_capi_embed_rgb(facedetect_ctx* ctx, const unsigned char* rgb,
                                         int width, int height, float** out_vec,
                                         int* out_dim) {
    if (!ctx || !ctx->model || !rgb || !out_vec || !out_dim) return 1;
    try {
        fd::Image img;
        if (!fd::image_from_rgb(rgb, width, height, img)) {
            set_error(ctx, "invalid rgb image dimensions");
            return 2;
        }
        std::vector<float> emb = ctx->model->embed(img);
        float* buf = dup_vec(emb);
        if (!buf) { set_error(ctx, "out of memory"); return 3; }
        *out_vec = buf;
        *out_dim = (int)emb.size();
        return 0;
    } catch (const std::exception& e) {
        set_error(ctx, e.what());
        return 4;
    } catch (...) {
        set_error(ctx, "unknown error");
        return 4;
    }
}

extern "C" char* facedetect_capi_detect_path_json(facedetect_ctx* ctx,
                                                  const char* image_path) {
    if (!ctx || !ctx->model || !image_path) return nullptr;
    try {
        fd::Image img;
        if (!fd::load_image_rgb(image_path, img)) {
            set_error(ctx, std::string("failed to load image: ") + image_path);
            return nullptr;
        }
        std::vector<fd::Detection> dets = ctx->model->detect(img);
        return dup_to_c(detections_to_json(dets));
    } catch (const std::exception& e) {
        set_error(ctx, e.what());
        return nullptr;
    } catch (...) {
        set_error(ctx, "unknown error");
        return nullptr;
    }
}

extern "C" int facedetect_capi_verify_paths(facedetect_ctx* ctx, const char* a,
                                            const char* b, float threshold,
                                            int anti_spoof, float* out_distance,
                                            int* out_verified) {
    if (!ctx || !ctx->model || !a || !b || !out_distance || !out_verified) return 1;
    try {
        const float thr = threshold > 0.0f ? threshold : ctx->model->config().verify_threshold;
        fd::Image ia, ib;
        if (!fd::load_image_rgb(a, ia)) { set_error(ctx, std::string("failed to load image: ") + a); return 2; }
        if (!fd::load_image_rgb(b, ib)) { set_error(ctx, std::string("failed to load image: ") + b); return 2; }
        std::vector<float> ea = ctx->model->embed(ia);
        std::vector<float> eb = ctx->model->embed(ib);
        double dot = 0.0;
        const size_t n = ea.size() < eb.size() ? ea.size() : eb.size();
        for (size_t i = 0; i < n; ++i) dot += (double)ea[i] * (double)eb[i];
        const float dist = (float)(1.0 - dot);
        *out_distance = dist;
        int verified = dist <= thr ? 1 : 0;
        // Anti-spoof veto: when requested and the pack carries the MiniFASNet
        // ensemble, a face judged fake in EITHER image forces not-verified.
        if (verified && anti_spoof != 0 && ctx->model->config().antispoof_present) {
            auto live = [&](const fd::Image& im) -> bool {
                std::vector<fd::Detection> d = ctx->model->detect(im);
                if (d.empty()) return false;  // no face -> cannot prove liveness
                const fd::Detection& primary = *std::max_element(
                    d.begin(), d.end(), [](const fd::Detection& x, const fd::Detection& y) {
                        return (x.x2 - x.x1) * (x.y2 - x.y1) < (y.x2 - y.x1) * (y.y2 - y.y1);
                    });
                return ctx->model->is_real(im, primary);
            };
            if (!live(ia) || !live(ib)) verified = 0;
        }
        *out_verified = verified;
        return 0;
    } catch (const std::exception& e) {
        set_error(ctx, e.what());
        return 4;
    } catch (...) {
        set_error(ctx, "unknown error");
        return 4;
    }
}

extern "C" char* facedetect_capi_analyze_path_json(facedetect_ctx* ctx,
                                                   const char* image_path) {
    if (!ctx || !ctx->model || !image_path) return nullptr;
    try {
        fd::Image img;
        if (!fd::load_image_rgb(image_path, img)) {
            set_error(ctx, std::string("failed to load image: ") + image_path);
            return nullptr;
        }
        std::vector<fd::Face> faces = ctx->model->analyze(img);
        std::string out = "{\"faces\":[";
        for (size_t i = 0; i < faces.size(); ++i) {
            const fd::Face& f = faces[i];
            if (i) out += ',';
            char b[256];
            std::snprintf(b, sizeof(b),
                          "{\"score\":%.4f,\"box\":[%.2f,%.2f,%.2f,%.2f],\"age\":%d,\"gender\":",
                          f.det.score, f.det.x1, f.det.y1, f.det.x2, f.det.y2, f.age);
            out += b;
            const std::string g(1, f.gender);
            json_escape(out, g);
            out += '}';
        }
        out += "]}";
        return dup_to_c(out);
    } catch (const std::exception& e) {
        set_error(ctx, e.what());
        return nullptr;
    } catch (...) {
        set_error(ctx, "unknown error");
        return nullptr;
    }
}

#ifndef FACEDETECT_CAPI_H
#define FACEDETECT_CAPI_H

#ifdef __cplusplus
extern "C" {
#endif

// Flat C-API for face-detect.cpp - designed for dlopen / cgo / purego (LocalAI).
//
// All functions are extern "C" and never let a C++ exception cross the
// boundary. A model pack is loaded ONCE into an opaque `facedetect_ctx` and
// reused across calls. Returned strings are malloc'd UTF-8 owned by the caller
// and must be released with facedetect_capi_free_string; returned float vectors
// are malloc'd and released with facedetect_capi_free_vec.
//
// This is the surface LocalAI's face-recognition (biometric) backend dlopens,
// replacing the Python `insightface` backend. The full pipeline is: decode
// image -> SCRFD detect -> 5-landmark similarity-transform align to 112x112
// (insightface norm_crop) -> ArcFace embed -> L2-normalized 512-d embedding,
// plus verify / analyze / detect and an optional MiniFASNet anti-spoof veto.

// Opaque face-recognition context (wraps a loaded model pack + last-error buffer).
typedef struct facedetect_ctx facedetect_ctx;

// ABI version of this header/implementation. Bump on any breaking change to the
// function signatures or semantics below. Additive changes (new functions) are
// fine without a bump.
//
// CHANGELOG
// ---------
// v1: initial surface - load/free, last-error, embed_path / embed_rgb (+
//     free_vec), detect_path_json, verify_paths, analyze_path_json.
int facedetect_capi_abi_version(void);

// Load a GGUF model pack (SCRFD detector + ArcFace recognizer, and optionally
// the genderage + MiniFASNet anti-spoof heads). Returns an owning context, or
// NULL on failure. The returned context must be released with
// facedetect_capi_free.
facedetect_ctx* facedetect_capi_load(const char* gguf_path);

// Free a context obtained from facedetect_capi_load. Safe on NULL.
void facedetect_capi_free(facedetect_ctx* ctx);

// Human-readable description of the last error on `ctx`, or "" if none. The
// returned pointer is owned by the context and valid until the next call on it
// (or until facedetect_capi_free). Returns "" if `ctx` is NULL.
const char* facedetect_capi_last_error(facedetect_ctx* ctx);

// Free a string previously returned by facedetect_capi_detect_path_json /
// facedetect_capi_analyze_path_json. Safe on NULL.
void facedetect_capi_free_string(char* s);

// Free a float vector previously returned via facedetect_capi_embed_path /
// facedetect_capi_embed_rgb. Safe on NULL.
void facedetect_capi_free_vec(float* v);

// Detect the primary (largest / highest-scoring) face in an image FILE, align it
// to 112x112 (insightface norm_crop) and run ArcFace, returning the
// L2-normalized embedding. On success returns 0 and writes a malloc'd float
// array of length `*out_dim` (typically 512) to `*out_vec` (release with
// facedetect_capi_free_vec). On error returns nonzero, sets the context's last
// error (see facedetect_capi_last_error), and leaves `*out_vec`/`*out_dim`
// unchanged.
int facedetect_capi_embed_path(facedetect_ctx* ctx, const char* image_path,
                               float** out_vec, int* out_dim);

// Like facedetect_capi_embed_path but from raw, tightly-packed 8-bit RGB pixels
// (`rgb`, `width`*`height`*3 bytes, row-major, no padding). Same return /
// ownership contract.
int facedetect_capi_embed_rgb(facedetect_ctx* ctx, const unsigned char* rgb,
                              int width, int height, float** out_vec, int* out_dim);

// Detect ALL faces in an image FILE, returning a malloc'd UTF-8 JSON document
// (free with facedetect_capi_free_string) of the form:
//
//   {"faces":[{"score":0.9971,
//              "box":[x1,y1,x2,y2],
//              "landmarks":[[x,y],[x,y],[x,y],[x,y],[x,y]]}, ...]}
//
// where "box" is the detection rectangle in pixel coordinates and "landmarks"
// are the 5 facial keypoints (left eye, right eye, nose, left mouth, right
// mouth), the same order insightface emits. Returns NULL on error and sets the
// context's last error.
char* facedetect_capi_detect_path_json(facedetect_ctx* ctx, const char* image_path);

// Verify whether two images contain the same identity. Each image is run through
// the detect+align+embed pipeline (primary face); the cosine DISTANCE
// (1 - cosine_similarity) between the two embeddings is written to
// `*out_distance` and `*out_verified` is set to 1 iff the distance is <=
// `threshold` (insightface buffalo default 0.35; pass <=0 to use the default).
// When `anti_spoof` is nonzero and the pack carries the MiniFASNet ensemble, a
// spoofed face vetoes the match (`*out_verified` forced to 0). On success
// returns 0; on error returns nonzero, sets the context's last error, and
